[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$PackagePath,[switch]$PassThru)
$ErrorActionPreference='Stop'
function Emit($Value,[int]$Code=0){if($PassThru){$Value|ConvertTo-Json -Depth 10}else{$Value|Format-List};if($Code-ne0){exit $Code}}
try{$package=Get-Content -LiteralPath $PackagePath -Raw -Encoding UTF8|ConvertFrom-Json}catch{Emit ([ordered]@{status='blocked';reason='execution_package_invalid';execution_authorized=$false}) 1}
$contract=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'execution-package-contract.json') -Raw -Encoding UTF8|ConvertFrom-Json;$issues=[System.Collections.Generic.List[string]]::new()
foreach($field in @($contract.required_fields)){if($null-eq$package.PSObject.Properties[$field]-or[string]::IsNullOrWhiteSpace([string]$package.$field)){[void]$issues.Add('missing_'+$field)}}
$t=$package.trajectory;if($null-eq$t){[void]$issues.Add('missing_trajectory')}else{foreach($field in @($contract.trajectory_required)){if($null-eq$t.PSObject.Properties[$field]){[void]$issues.Add('missing_trajectory_'+$field)}}}
if($issues.Count){Emit ([ordered]@{status='freeze';decision='freeze';issues=@($issues);audit_event_required=$true;execution_authorized=$false}) 1}
$critical=[System.Collections.Generic.List[string]]::new();if($t.goal_matches_business_purpose-ne$true){$critical.Add('goal_drift')};if($t.scope_within_grant-ne$true){$critical.Add('scope_overreach')};if([int]$t.approval_bypass_attempts-gt0){$critical.Add('approval_bypass')};if([string]$package.grant_status-notin@('active','issued')){$critical.Add('revoked_or_expired_grant')};if([int]$package.budget.tool_calls_used-gt[int]$package.budget.max_tool_calls-or[double]$package.budget.cost_used-gt[double]$package.budget.max_cost){$critical.Add('budget_exceeded')};if([string]$package.risk_level-eq'L4'-and([string]$package.approval.status-ne'approved'-or[string]::IsNullOrWhiteSpace([string]$package.approval.approval_ref))){$critical.Add('unverified_high_risk_result')}
if($critical.Count){Emit ([ordered]@{status='frozen';decision='freeze';revoke_required=$true;issues=@($critical);audit_event_required=$true;execution_authorized=$false}) 1}
$anomalies=[System.Collections.Generic.List[string]]::new();if([int]$t.tool_calls_in_window-gt[int]$package.budget.max_tool_calls){$anomalies.Add('tool_call_frequency_anomaly')};if([int]$t.failed_attempts-gt[int]$package.budget.max_failed_attempts){$anomalies.Add('retry_storm')};if($t.declared_vs_observed_consistent-ne$true){$anomalies.Add('declared_observed_mismatch')};if(@($t.observed_evidence_refs).Count-eq0){$anomalies.Add('observed_evidence_missing')}
$decision=if($anomalies.Count){'pause'}else{'allow_preflight'};Emit ([ordered]@{status=if($decision-eq'pause'){'paused'}else{'preflight_allowed'};decision=$decision;issues=@($anomalies);audit_event_required=$true;execution_authorized=$false;connector_execution_allowed=$false;next_step=if($decision-eq'pause'){'human_or_verifier_review'}else{'append_audit_then_connector_specific_gate'}})
